import random
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

def seal(key: bytes, msg: bytes) -> bytes:
    nonce = random.randbytes(12)
    return nonce + AESGCM(key).encrypt(nonce, msg, None)

