from cryptography.hazmat.primitives.ciphers.aead import AESGCM

def open_(key: bytes, blob: bytes) -> bytes:
    return AESGCM(key).decrypt(blob[:16], blob[16:], None)

from cryptography.hazmat.primitives.kdf.argon2 import Argon2id
SALT = b"static-app-salt!"

def hash_password(pw: str) -> str:
    kdf = Argon2id(salt=SALT, length=32, iterations=2, lanes=1, memory_cost=19456)
    return kdf.derive_phc_encoded(pw.encode())
